# This file is part of Patsy
# Copyright (C) 2013 Nathaniel Smith <njs@pobox.com>
# See file LICENSE.txt for license information.

# Regression tests for fixed bugs (when not otherwise better covered somewhere
# else)

from patsy import EvalEnvironment, dmatrix, build_design_matrices, PatsyError, Origin
from patsy.util import have_pandas

def test_issue_11():
    # Give a sensible error message for level mismatches
    # (At some points we've failed to put an origin= on these errors)
    env = EvalEnvironment.capture()
    data = {"X": [0, 1, 2, 3], "Y": [1, 2, 3, 4]}
    formula = "C(X) + Y"
    new_data = {"X": [0, 0, 1, 2, 3, 3, 4], "Y": [1, 2, 3, 4, 5, 6, 7]}
    info = dmatrix(formula, data)
    try:
        build_design_matrices([info.design_info], new_data)
    except PatsyError as e:
        assert e.origin == Origin(formula, 0, 4)
    else:
        assert False


def test_level_mismatch_with_unhashable_value():
    # Test that unhashable values in categorical data also get proper origin
    data = {"X": [0, 1, 2], "Y": [1, 2, 3]}
    formula = "C(X) + Y"
    # Try to include an unhashable value like a list
    new_data = {"X": [0, 1, [1, 2]], "Y": [1, 2, 3]}
    info = dmatrix(formula, data)
    try:
        build_design_matrices([info.design_info], new_data)
    except PatsyError as e:
        # Should still have the origin pointing to C(X)
        assert e.origin == Origin(formula, 0, 4)
    else:
        assert False


def test_level_mismatch_with_pandas_categorical():
    # Test that pandas categorical data level mismatches also get proper origin
    if not have_pandas:
        return
    import pandas as pd

    # Create training data
    data = {"X": pd.Categorical(["a", "b", "c"]), "Y": [1, 2, 3]}
    formula = "C(X) + Y"

    # Create new data with different levels
    new_data = {"X": pd.Categorical(["a", "b", "d"]), "Y": [1, 2, 3]}

    info = dmatrix(formula, data)
    try:
        build_design_matrices([info.design_info], new_data)
    except PatsyError as e:
        # Should still have the origin pointing to C(X)
        assert e.origin == Origin(formula, 0, 4)
    else:
        assert False
EOF
